globals:
inline bool memoria_nombre(const String& nombre, const char* bloque) {
    bool valido = nombre.length() >= 1 && nombre.length() <= 12;
    for (unsigned int i = 0; i < nombre.length(); i++) {
        char c = nombre[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_')) valido = false;
    }
    if (!valido) rb_fail(bloque, "Nombre de memoria invalido: usa 1 a 12 letras, digitos o _");
    return valido;
}
#if defined(ESP32) || defined(ARDUINO_ARCH_ESP32)
inline bool memoria_buscar(const String& nombre, float& valor, bool& existe, const char* bloque) {
    Preferences memoria_prefs;
    if (!memoria_prefs.begin("greyforge", false)) { rb_fail(bloque, "No se pudo acceder a la memoria"); return false; }
    existe = memoria_prefs.isKey(nombre.c_str());
    if (existe) valor = memoria_prefs.getFloat(nombre.c_str(), 0);
    memoria_prefs.end();
    return true;
}
inline void memoria_escribir(const String& nombre, float valor, const char* bloque) {
    Preferences memoria_prefs;
    if (!memoria_prefs.begin("greyforge", false)) { rb_fail(bloque, "No se pudo acceder a la memoria"); return; }
    if (memoria_prefs.putFloat(nombre.c_str(), valor) != sizeof(float)) rb_fail(bloque, "No se pudo acceder a la memoria");
    memoria_prefs.end();
}
inline void memoria_borrar(const char* bloque) {
    Preferences memoria_prefs;
    if (!memoria_prefs.begin("greyforge", false)) { rb_fail(bloque, "No se pudo acceder a la memoria"); return; }
    if (!memoria_prefs.clear()) rb_fail(bloque, "No se pudo acceder a la memoria");
    memoria_prefs.end();
}
