// Claves «/kv/gf_<nombre>»: borrar quita solo las de GreyForge y deja el resto del KVStore.
inline void memoria_clave(char* clave, size_t largo, const String& nombre) {
    snprintf(clave, largo, "/kv/gf_%s", nombre.c_str());
}
inline bool memoria_buscar(const String& nombre, float& valor, bool& existe, const char* bloque) {
    char clave[24];
    memoria_clave(clave, sizeof(clave), nombre);
    size_t leidos = 0;
    int resultado = kv_get(clave, &valor, sizeof(valor), &leidos);
    existe = resultado != MBED_ERROR_ITEM_NOT_FOUND;
    if (!existe) return true;
    if (resultado != MBED_SUCCESS || leidos != sizeof(valor)) { rb_fail(bloque, "No se pudo acceder a la memoria"); return false; }
    return true;
}
inline void memoria_escribir(const String& nombre, float valor, const char* bloque) {
    char clave[24];
    memoria_clave(clave, sizeof(clave), nombre);
    if (kv_set(clave, &valor, sizeof(valor), 0) != MBED_SUCCESS) rb_fail(bloque, "No se pudo acceder a la memoria");
