inline void memoria_borrar(const char* bloque) {
    kv_iterator_t lista;
    if (kv_iterator_open(&lista, "/kv/gf_") != MBED_SUCCESS) { rb_fail(bloque, "No se pudo acceder a la memoria"); return; }
    char clave[32];
    char ruta[40];
    bool correcto = true;
    while (kv_iterator_next(lista, clave, sizeof(clave)) == MBED_SUCCESS) {
        // El iterador devuelve la clave sin «/kv/»; se acepta también la ruta completa.
        if (clave[0] == '/') snprintf(ruta, sizeof(ruta), "%s", clave);
        else snprintf(ruta, sizeof(ruta), "/kv/%s", clave);
        if (kv_remove(ruta) != MBED_SUCCESS) correcto = false;
    }
    kv_iterator_close(lista);
    if (!correcto) rb_fail(bloque, "No se pudo acceder a la memoria");
}
