// «usar EEPROM I2C para la memoria» cambia el almacén; sin ese bloque se usa el de la tarjeta.
typedef bool (*MemoriaBuscar)(const String& nombre, float& valor, bool& existe, const char* bloque);
typedef void (*MemoriaEscribir)(const String& nombre, float valor, const char* bloque);
typedef void (*MemoriaBorrar)(const char* bloque);
static MemoriaBuscar memoria_externa_buscar = nullptr;
static MemoriaEscribir memoria_externa_escribir = nullptr;
static MemoriaBorrar memoria_externa_borrar = nullptr;
inline bool memoria_consultar(const String& nombre, float& valor, bool& existe, const char* bloque) {
    if (memoria_externa_buscar) return memoria_externa_buscar(nombre, valor, existe, bloque);
    return memoria_buscar(nombre, valor, existe, bloque);
}
inline void memoria_vaciar(const char* bloque) {
    if (memoria_externa_borrar) memoria_externa_borrar(bloque);
    else memoria_borrar(bloque);
}
inline void memoria_guardar(const String& nombre, float valor, const char* bloque) {
    if (!memoria_nombre(nombre, bloque)) return;
    float anterior = 0; bool existe = false;
    if (!memoria_consultar(nombre, anterior, existe, bloque)) return;
    if (existe && anterior == valor) return;
    if (memoria_externa_escribir) memoria_externa_escribir(nombre, valor, bloque);
    else memoria_escribir(nombre, valor, bloque);
}
inline float memoria_leer(const String& nombre, float predeterminado, const char* bloque) {
    if (!memoria_nombre(nombre, bloque)) return predeterminado;
    float valor = 0; bool existe = false;
    if (!memoria_consultar(nombre, valor, existe, bloque)) return predeterminado;
    return existe ? valor : predeterminado;
}
inline bool memoria_hay(const String& nombre, const char* bloque) {
    if (!memoria_nombre(nombre, bloque)) return false;
    float valor = 0; bool existe = false;
    return memoria_consultar(nombre, valor, existe, bloque) && existe;
}

// EEPROM I2C externa de 32 Kbit o más (24C32…24C512): dirección interna de 2 bytes.
// Formato GFM1 v2: cabecera «GFM1», 2, 64, 0, 0 y 64 entradas de 20 bytes desde la dirección 8:
// nombre[12] rellenado con ceros, float32 LE, CRC16-CCITT del nombre y el número (LE), 0, 0.
// Las entradas van seguidas; la primera cuyo nombre empieza con 0x00 o 0xff marca el final.
static TwoWire* memoria_i2c_bus = nullptr;
static uint8_t memoria_i2c_direccion = 0x50;
static int8_t memoria_i2c_estado = -1; // -1 sin leer, 0 vacía o de otro programa, 1 tabla GreyForge
static const uint8_t memoria_i2c_firma[8] = {'G', 'F', 'M', '1', 2, 64, 0, 0};
inline uint16_t memoria_i2c_crc(const uint8_t* datos, uint8_t largo) {
    uint16_t crc = 0xffff;
    for (uint8_t i = 0; i < largo; i++) {
        crc ^= uint16_t(datos[i]) << 8;
        for (int bit = 0; bit < 8; bit++) crc = (crc & 0x8000) ? uint16_t((crc << 1) ^ 0x1021) : uint16_t(crc << 1);
    }
    return crc;
}
inline bool memoria_i2c_leer(uint16_t direccion, uint8_t* datos, uint8_t largo) {
    while (largo) {
        uint8_t parte = largo > 16 ? 16 : largo;
        memoria_i2c_bus->beginTransmission(memoria_i2c_direccion);
        memoria_i2c_bus->write(uint8_t(direccion >> 8));
        memoria_i2c_bus->write(uint8_t(direccion & 0xff));
        if (memoria_i2c_bus->endTransmission(false) != 0) return false;
        if (memoria_i2c_bus->requestFrom(memoria_i2c_direccion, parte) != parte) return false;
        for (uint8_t i = 0; i < parte; i++) {
            int valor = memoria_i2c_bus->read();
            if (valor < 0) return false;
            datos[i] = uint8_t(valor);
        }
        direccion += parte; datos += parte; largo -= parte;
    }
    return true;
}
// Tras escribir, el chip no responde hasta terminar (unos 5 ms): se pregunta hasta 20 ms.
inline bool memoria_i2c_esperar() {
    for (int intento = 0; intento < 80; intento++) {
        memoria_i2c_bus->beginTransmission(memoria_i2c_direccion);
        if (memoria_i2c_bus->endTransmission() == 0) return true;
        delayMicroseconds(250);
    }
    return false;
}
// Escribe en trozos de 16 bytes alineados (nunca cruzan una página) y solo los que cambian.
inline bool memoria_i2c_escribir(uint16_t direccion, const uint8_t* datos, uint8_t largo) {
    while (largo) {
        uint8_t parte = uint8_t(16 - direccion % 16);
        if (parte > largo) parte = largo;
        uint8_t actual[16];
        if (!memoria_i2c_leer(direccion, actual, parte)) return false;
        if (memcmp(actual, datos, parte) != 0) {
            memoria_i2c_bus->beginTransmission(memoria_i2c_direccion);
            memoria_i2c_bus->write(uint8_t(direccion >> 8));
            memoria_i2c_bus->write(uint8_t(direccion & 0xff));
            for (uint8_t i = 0; i < parte; i++) memoria_i2c_bus->write(datos[i]);
            if (memoria_i2c_bus->endTransmission() != 0) return false;
            if (!memoria_i2c_esperar()) return false;
        }
        direccion += parte; datos += parte; largo -= parte;
    }
    return true;
}
inline bool memoria_i2c_revisar(const char* bloque) {
    if (memoria_i2c_estado >= 0) return true;
    uint8_t cabecera[8];
    if (!memoria_i2c_leer(0, cabecera, 8)) { rb_fail(bloque, "No responde la EEPROM I2C"); return false; }
    // Una EEPROM nueva o con datos de otro programa se lee como vacía; guardar la prepara.
    memoria_i2c_estado = memcmp(cabecera, memoria_i2c_firma, 8) == 0 ? 1 : 0;
    return true;
}
// Devuelve el índice del nombre, -1 si no está (con «libre» en la primera entrada vacía) o -2 si falla.
inline int memoria_i2c_indice(const String& nombre, uint8_t* entrada, uint8_t& libre, const char* bloque) {
    libre = 0;
    if (memoria_i2c_estado != 1) return -1;
    for (uint8_t i = 0; i < 64; i++) {
        if (!memoria_i2c_leer(uint16_t(8 + i * 20), entrada, 20)) { rb_fail(bloque, "No responde la EEPROM I2C"); return -2; }
        if (entrada[0] == 0 || entrada[0] == 0xff) { libre = i; return -1; }
        uint16_t crc = memoria_i2c_crc(entrada, 16);
        if (entrada[16] != uint8_t(crc & 0xff) || entrada[17] != uint8_t(crc >> 8)) {
            rb_fail(bloque, "Memoria danada: borra los numeros guardados"); return -2;
        }
        bool igual = true;
        for (int c = 0; c < 12; c++) if (entrada[c] != (c < int(nombre.length()) ? uint8_t(nombre[c]) : 0)) igual = false;
        if (igual) return i;
    }
    libre = 64;
    return -1;
}
inline bool memoria_i2c_buscar(const String& nombre, float& valor, bool& existe, const char* bloque) {
    if (!memoria_i2c_revisar(bloque)) return false;
    uint8_t entrada[20];
    uint8_t libre = 0;
    int indice = memoria_i2c_indice(nombre, entrada, libre, bloque);
    if (indice == -2) return false;
    existe = indice >= 0;
    if (existe) {
        uint32_t bits = 0;
        for (int c = 0; c < 4; c++) bits |= uint32_t(entrada[12 + c]) << (8 * c);
        memcpy(&valor, &bits, 4);
    }
    return true;
}
// Primero el final de la tabla y después la firma: un corte a mitad deja la tabla vacía.
inline void memoria_i2c_borrar(const char* bloque) {
    uint8_t fin = 0;
    if (!memoria_i2c_escribir(8, &fin, 1) || !memoria_i2c_escribir(0, memoria_i2c_firma, 8)) {
        rb_fail(bloque, "No responde la EEPROM I2C"); return;
    }
    memoria_i2c_estado = 1;
}
inline void memoria_i2c_guardar(const String& nombre, float valor, const char* bloque) {
    if (!memoria_i2c_revisar(bloque)) return;
    if (memoria_i2c_estado != 1) memoria_i2c_borrar(bloque);
    if (rb_failed) return;
    uint8_t entrada[20];
    uint8_t libre = 0;
    int indice = memoria_i2c_indice(nombre, entrada, libre, bloque);
    if (indice == -2) return;
    if (indice < 0) {
        if (libre >= 64) { rb_fail(bloque, "Memoria llena: maximo 64 numeros"); return; }
        indice = libre;
        // El nuevo final va antes que la entrada, para que la tabla siempre termine.
        uint8_t fin = 0;
        if (indice + 1 < 64 && !memoria_i2c_escribir(uint16_t(8 + (indice + 1) * 20), &fin, 1)) {
            rb_fail(bloque, "No responde la EEPROM I2C"); return;
        }
    }
    for (int c = 0; c < 12; c++) entrada[c] = c < int(nombre.length()) ? uint8_t(nombre[c]) : 0;
    uint32_t bits = 0;
    memcpy(&bits, &valor, 4);
    for (int c = 0; c < 4; c++) entrada[12 + c] = uint8_t(bits >> (8 * c));
    uint16_t crc = memoria_i2c_crc(entrada, 16);
    entrada[16] = uint8_t(crc & 0xff); entrada[17] = uint8_t(crc >> 8); entrada[18] = 0; entrada[19] = 0;
    // La primera letra del nombre se escribe al final: la entrada aparece solo cuando está completa.
    uint16_t inicio = uint16_t(8 + indice * 20);
    if (!memoria_i2c_escribir(inicio + 1, entrada + 1, 19) || !memoria_i2c_escribir(inicio, entrada, 1))
        rb_fail(bloque, "No responde la EEPROM I2C");
}
inline void memoria_i2c_usar(TwoWire& bus, const String& direccion, const char* bloque) {
    // El menú da «0x50» … «0x57».
    memoria_i2c_bus = &bus;
    memoria_i2c_direccion = uint8_t(0x50 + (direccion.length() == 4 ? direccion[3] - '0' : 0));
    memoria_i2c_estado = -1;
    bus.beginTransmission(memoria_i2c_direccion);
    if (bus.endTransmission() != 0) { rb_fail(bloque, "No hay EEPROM I2C en esa direccion"); return; }
    memoria_externa_buscar = memoria_i2c_buscar;
    memoria_externa_escribir = memoria_i2c_guardar;
    memoria_externa_borrar = memoria_i2c_borrar;
}

inline bool memoria_nombre(const String& nombre, const char* bloque) {
    bool valido = nombre.length() >= 1 && nombre.length() <= 12;
    for (unsigned int i = 0; i < nombre.length(); i++) {
        char c = nombre[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_')) valido = false;
    }
    if (!valido) rb_fail(bloque, "Nombre de memoria invalido: usa 1 a 12 letras, digitos o _");
    return valido;
}
